def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Rectangular frames mark their enclosed interior with color 4.
    for top in range(h):
        for bottom in range(top + 2, h):
            for left in range(w):
                for right in range(left + 2, w):
                    if (all(grid[top][c] == grid[bottom][c] == 9 for c in range(left, right + 1))
                        and all(grid[r][left] == grid[r][right] == 9 for r in range(top, bottom + 1))):
                        for r in range(top + 1, bottom):
                            for c in range(left + 1, right):
                                out[r][c] = 4
    return out
